@WebServlet("/halo")
class HaloServlet extends HttpServlet {
    private int dilayani;

    @Override
    public void init() {
        System.out.println("[init] " + getServletName());
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res) throws IOException {
        dilayani++;
        res.setContentType("text/plain;charset=UTF-8");
        res.getWriter().print("Halo dari Todolist Web, permintaan ke-" + dilayani);
    }

    @Override
    public void destroy() {
        System.out.println("[destroy] setelah " + dilayani + " permintaan");
    }
}

@WebServlet("/versi")
class VersiServlet extends HttpServlet {
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res) throws IOException {
        res.setContentType("text/plain;charset=UTF-8");
        res.getWriter().print("Todolist Web versi 1.0");
    }
}

